            <div>
              <div className="mb-8">
                <span className="text-3xl lg:text-4xl font-extrabold tracking-tighter text-white">
                  Yafu <span className="text-gradient">AI</span>
                </span>
              </div>

              <h2 className="text-4xl lg:text-6xl font-black mb-6 tracking-tight leading-tight text-[#FFF8DE]">
                Ready to Transform Your <br />
                <span className="text-gradient">Business with AI?</span>
              </h2>

              <p className="text-lg text-[#B7BDF7]/80 mb-8 leading-relaxed">
                Fill out the form to get a custom strategy. We'll show you exactly how Yafu AI can automate your growth.
              </p>

              <div className="space-y-4 mb-8">
                <div className="flex items-center gap-3 text-sm text-[#FFF8DE]/70">
                  <ShieldCheck className="w-5 h-5 text-[#FF7444] shrink-0" />
                  No commitment required
                </div>
                <div className="flex items-center gap-3 text-sm text-[#FFF8DE]/70">
                  <Clock className="w-5 h-5 text-[#B7BDF7] shrink-0" />
