                </div>
                <div className="flex items-center gap-3 text-sm text-[#FFF8DE]/70">
                  <Target className="w-5 h-5 text-[#576A8F] shrink-0" />
                  Custom AI blueprint included
                </div>
              </div>
            </div>

            <div className="glass-card p-8 rounded-3xl bg-white/5 border border-white/10">
              {status === 'success' ? (
                <div className="h-full flex flex-col items-center justify-center text-center py-12 animate-in fade-in zoom-in duration-500">
                  <div className="w-20 h-20 bg-[#FF7444]/20 rounded-full flex items-center justify-center mb-6">
                    <Send className="text-[#FF7444] w-10 h-10" />
                  </div>
                  <h3 className="text-2xl font-bold mb-2 text-[#FFF8DE]">Message Received!</h3>
                  <p className="text-[#B7BDF7]/80">
                    We'll get back to you at <strong>amanlakhotra@yafuai.online</strong> shortly. 
                    <br />Please check your inbox.
                  </p>
                </div>
              ) : (
                <form onSubmit={handleSubmit} className="space-y-5">
                  <input type="hidden" name="_subject" value="New Lead from Yafu AI Website" />
