        {/* Desktop Nav */}
        <div className="hidden md:flex items-center gap-8">
          {navLinks.map((link) => (
            <button 
              key={link.name} 
              onClick={(e) => scrollTo(e, link.href)} 
              className="text-sm font-medium text-[#576A8F]/70 hover:text-[#FF7444] transition-colors outline-none"
            >
              {link.name}
            </button>
