              onClick={(e) => scrollTo(e, link.href)}
              className="text-left text-lg font-medium text-[#576A8F]/70 hover:text-[#FF7444] py-2 outline-none"
            >
              {link.name}
            </button>
          ))}
          <button 
            onClick={(e) => scrollTo(e, '#booking')} 
            className="btn-gradient px-6 py-3 rounded-xl text-center font-semibold outline-none"
          >
            Book a Call
          </button>
        </div>
      )}
